function icon(type){const shapes={temperature:'<path d="M14 14.5V5a3 3 0 0 0-6 0v9.5a5 5 0 1 0 6 0Z"/><path d="M11 8v9"/><circle cx="11" cy="18" r="1.7" fill="currentColor" stroke="none"/><path d="M17 6h3m-3 4h2"/>',oxygen:'<circle cx="12" cy="12" r="9"/><text x="4.5" y="16" font-size="11" font-family="Arial,sans-serif" font-weight="700" fill="currentColor" stroke="none">O₂</text>',salinity:'<path d="M12 2S4 10.5 4 15a8 8 0 0 0 16 0c0-4.5-8-13-8-13Z"/><path d="M8 16a4 4 0 0 0 4 4"/>'};return '<span class="metric-icon '+type+'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+shapes[type]+'</svg></span>'}
const $=s=>document.querySelector(s);let page='home',fault=false,condition='변화 없음',record=null,completed=false;
try{record=JSON.parse(localStorage.getItem('blue-shelter-record')||'null');completed=!!record&&record.length!=='0'}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function go(p){page=p;render();$('#screen').focus({preventScroll:true})}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2600)}
function ocean(){return `<div class="ocean" role="img" aria-label="1m 고수온, 3m 비교적 양호, 5m 산소 부족. 현재 굴 구간 2~5m, 조절 후보 2~4m."><div class="depth-row" style="top:25px"><div><strong>1m</strong>29.1℃ · 산소 6.2</div><span class="water-label">고수온 주의</span></div><div class="depth-row" style="top:125px"><div><strong>3m</strong>26.8℃ · 산소 5.8</div><span class="water-label">비교적 양호</span></div><div class="depth-row low" style="top:235px"><div><strong>5m</strong>${fault?'측정값 확인 필요':'24.8℃ · 산소 2.8'}</div><span class="water-label">${fault?'센서 이상':'산소 부족'}</span></div><div class="ropes">${[0,1,2].map(()=>`<div class="rope" style="height:${completed?250-Number(record.length)*60:250}px"><i class="shell"></i><i class="shell" style="bottom:45px"></i><i class="shell" style="bottom:90px"></i></div>`).join('')}</div><div class="rope-tag" style="top:${completed?270-Number(record.length)*60:270}px">${completed?'조절 후 2~'+(5-Number(record.length))+'m':'현재 굴 분포 2~5m'}</div></div>`}
function home(){return `<h2 class="screen-title">우리 양식장, 지금은</h2><div class="status ${fault?'fault':completed?'good':''}"><span class="tag">${pictogram(fault?'alert':completed?'check':'alert')} 현재 상태: <b>${fault?'확인 필요':completed?'기록 완료':'주의'}</b></span><p>${fault?'5m 센서 점검이 필요해요':completed?'작업 후 새 측정값을 기다려요':'아래쪽 수심의 산소가 부족해요'}</p></div><div class="section-label"><span>현재값 · <b>3m 수심</b></span><span>현장 센서 · 가상</span></div><div class="metric"><span class="name">${icon('temperature')} 수온</span><div><strong>26.8<small>℃</small></strong><span class="hint">상층 1m는 고수온 주의</span></div></div><div class="metric"><span class="name">${icon('oxygen')} 용존산소</span><div><strong>5.8<small>mg/L</small></strong><span class="hint">3m는 비교적 양호</span></div></div><div class="metric"><span class="name">${icon('salinity')} 염분</span><div><strong>29.5<small>PSU</small></strong><span class="hint">급격한 변화 없음</span></div></div><div class="measured">${pictogram('clock')} 최근 측정 10:30</div><div class="home-cta"><button class="primary" data-go="recommend">${pictogram('robot')} ${fault?'AI 추천 보류 안내':'AI 추천 보기'}</button><p class="micro">전체 굴 구간 2~5m 분석 · 시연용 기준 기반 추천</p></div>`}
function depths(){return `<h2 class="screen-title">수심별 상태</h2><p class="sub">차가운 곳도 산소가 부족할 수 있어요.</p>${[{d:1,t:'29.1',o:'6.2',s:'고수온 주의',c:''},{d:3,t:'26.8',o:'5.8',s:'비교적 양호',c:'green'},{d:5,t:'24.8',o:'2.8',s:fault?'측정 확인 필요':'산소 부족',c:'red'}].map(x=>`<div class="depth-card"><div class="depth-number">${x.d}m</div><div class="depth-data">${fault&&x.d===5?'센서 이상 · 값 사용 보류':`수온 <b>${x.t}℃</b><br>산소 <b>${x.o} mg/L</b>`}<br><span class="pill ${x.c}">${x.s}</span></div></div>`).join('')}<div class="explain">현재 굴은 <b>2~5m</b>에 있어요.<br>시연 조절 가능 범위: 하단 1m 단축<br>상층의 열과 하층의 산소를 함께 비교해요.</div><button class="primary" data-go="recommend">${fault?'확인할 내용 보기':'AI 추천 보기'} →</button><details><summary>측정과 판단 기준 보기</summary>10분 간격의 가상 현장 센서 자료입니다. 시연 분류에는 수온 28℃ 이상 주의, 산소 3mg/L 미만 부족을 사용합니다. 실제 굴의 안전기준이 아니며 품종·생육단계·현장 검증으로 확정해야 합니다. 센서 사이 구간과 조절 효과는 현장 확인이 필요합니다.</details>`}
function recommend(){if(fault)return `<h2 class="screen-title">지금은 추천을 보류해요</h2><p class="sub">믿을 수 있는 측정값이 먼저예요.</p><div class="status fault"><span class="tag">! 5m 센서 확인 필요</span><h3>아래쪽 산소 상태를<br>정확히 알 수 없어요</h3><p>측정값 이상이 감지되어 해당 센서값을 추천에서 제외했어요.</p></div><ul class="reason"><li>센서에 이물질이 붙었거나 장비 오류일 수 있어요.</li><li>현장에서 센서를 점검하고 다시 측정해 주세요.</li><li>새 측정값이 확인될 때까지 조절안을 제시하지 않아요.</li></ul><button class="primary" data-go="device">센서 상태 확인하기 →</button><button class="secondary" data-go="home">홈으로 돌아가기</button>`;return `<h2 class="screen-title">AI 조절 추천</h2><p class="sub">AI 조절안 · 시연용 기준 기반 비교</p><div class="status good"><span class="tag">AI 분석 · 수하연 조절 추천</span><h3>아래쪽 줄을 1m<br>줄이는 안을 추천해요</h3><p>상단 위치를 유지하고 하단을 줄일 수 있는 시설을 가정했어요.</p></div>${adjustmentGraphic()}<div class="compare"><div>현재 굴 구간<strong>2~5m</strong>하단 산소 부족</div><div class="after">조절 후보<strong>2~4m</strong>위험층 접촉 축소 검토</div></div><ul class="reason"><li><b>1m 상층은 수온이 높아요.</b><br>전체 줄을 위로 올리는 안은 피했어요.</li><li><b>5m 하층은 산소가 부족해요.</b><br>하단을 줄이는 후보를 비교했어요.</li></ul><details><summary>추천 근거와 한계 자세히 보기</summary>3m 측정은 26.8℃·산소 5.8mg/L로 비교적 양호합니다. 4m는 직접 관측하지 않았으므로 2~4m 전체가 안전하다고 확정할 수 없습니다. 추가 측정과 실제 시설·작업 방식 확인이 필요합니다. 생존율 개선이나 자동 장비 작동을 의미하지 않습니다.</details><button class="primary" data-go="action">✓ 조치 진행</button><button class="secondary" id="later">나중에 확인</button>`}
function action(){if(fault)return recommend();return `<h2 class="screen-title">작업한 내용을 남겨요</h2><p class="sub">앱 버튼은 장비를 움직이지 않아요.<br>실제 작업 후 완료해 주세요.</p><div class="explain">추천 검토안: 하단 1m 단축<br>실제 작업 가능 여부는 현장에서 판단해 주세요.</div><label class="field" for="length">실제로 줄인 길이</label><select id="length"><option value="1">1m 줄였어요</option><option value="0.5">0.5m 줄였어요</option><option value="0">조절하지 않았어요</option></select><label class="field">눈으로 본 굴 상태</label><div class="choices">${['변화 없음','이상 의심','확인 못함'].map(c=>`<button data-condition="${c}" class="${condition===c?'selected':''}">${c}</button>`).join('')}</div><label class="field" for="memo">메모 (선택)</label><textarea id="memo" placeholder="현장에서 확인한 내용을 남겨 주세요" maxlength="300"></textarea><button class="primary" id="complete">✓ 작업 완료 기록하기</button><button class="secondary" data-go="recommend">추천 다시 보기</button>`}
function records(){return `<h2 class="screen-title">작업을 기록했어요</h2><p class="sub">${record?'조치 결과와 굴 상태를 함께 살펴보세요.':'아직 완료한 작업이 없어요.'}</p>${record?`<div class="status good"><span class="tag">✓ 기록 완료 · 이 브라우저에 저장</span><h3>${record.length==='0'?'현장 확인 완료':`하단 ${esc(record.length)}m 단축 기록`}</h3><p>${esc(record.time)}</p></div><div class="record"><b>현장 작업 기록</b><p>실제 단축: ${esc(record.length)}m<br>굴 상태: ${esc(record.condition)}<br>${esc(record.memo||'추가 메모 없음')}</p></div><div class="explain">${record.length==='1'?'기록상 굴 구간: 2~5m → 2~4m':record.length==='0.5'?'기록상 굴 구간: 2~5m → 2~4.5m':'기존 굴 구간 유지: 2~5m'}<br><b>조치 후 새 측정값은 아직 없어요.</b><br>환경 개선과 굴의 건강 개선은 후속 관측으로 확인해야 해요.</div>`:`<div class="explain">추천을 확인하고 작업을 기록하면 여기에 남아요.</div>`}<button class="primary" data-go="${record?'home':'recommend'}">${record?'우리 양식장으로':'추천 확인하기'} →</button>`}
function device(){return `<h2 class="screen-title">장비 상태</h2><p class="sub">마지막 통신 10:30 · 가상 장비</p><div class="device"><span>${pictogram('buoy')} 부표 연결</span><strong>정상</strong></div><div class="device"><span>${pictogram('battery')} 배터리</span><strong>82%</strong></div><div class="device"><span>${pictogram('sun')} 태양광</span><strong>충전 중</strong></div><div class="device"><span>${pictogram('alert')} 5m 산소 센서</span><strong class="${fault?'bad':''}">${fault?'점검 필요':'측정 중'}</strong></div><div class="device"><span>${pictogram('calendar')} 센서 점검 예정</span><strong>11월 12일</strong></div><div class="explain" style="margin-top:20px">${fault?'이물질 부착 또는 장비 오류가 의심돼요. 원인은 현장 점검이 필요해요.':'점검·세척 기록을 남기면 장비 상태를 꾸준히 관리할 수 있어요.'}</div><button class="primary" id="clean">${pictogram('clipboard')} 점검 기록 입력</button><p class="micro">기록만으로 센서가 정상 복구되지는 않아요. 재측정과 품질 확인이 필요합니다.</p>`}
function render(){ $('#screen').scrollTop=0; $('.location').innerHTML=page==='home'?'가막만 굴 양식장 A':({depths:'수심별 상태',recommend:'AI 조절 추천',action:'조치 기록',records:'조치 이력',device:'장비 상태'}[page]); $('#screen').innerHTML=({home,depths,recommend,action,records,device}[page]||home)();$('#ocean').innerHTML=ocean();$('#nav').innerHTML=[['home','⌂','홈'],['depths','≋','수심분석'],['records','▤','조치기록'],['device','⚙','장비관리']].map(([p,i,t])=>`<button data-go="${p}" class="${page===p||p==='depths'&&['recommend','action'].includes(page)?'active':''}" ${page===p?'aria-current="page"':''}><span>${pictogram(p==='home'?'home':p==='depths'?'waves':p==='records'?'clipboard':'gear')}</span>${t}</button>`).join('');$('#steps').innerHTML=[['home','상태 확인'],['recommend','추천 이해'],['action','직접 판단'],['records','작업 기록']].map(([p,t],i)=>`<button class="step ${page===p?'active':''}" data-go="${p}"><b>0${i+1}</b>${t}</button>`).join('');document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-condition]').forEach(b=>b.onclick=()=>{condition=b.dataset.condition;document.querySelectorAll('[data-condition]').forEach(x=>x.classList.toggle('selected',x===b))});if($('#later'))$('#later').onclick=()=>{toast('추천을 보류했어요. 현장 상태를 계속 확인해 주세요.');go('home')};if($('#complete'))$('#complete').onclick=()=>{record={length:$('#length').value,condition,memo:$('#memo').value.trim(),time:new Date().toLocaleString('ko-KR')};completed=record.length!=='0';try{localStorage.setItem('blue-shelter-record',JSON.stringify(record))}catch{}go('records');toast('작업 기록을 저장했어요')};if($('#clean'))$('#clean').onclick=()=>toast('점검 기록을 남겼어요. 재측정 후 정상 여부를 확인해 주세요.');}
$('#scenario').onchange=e=>{fault=e.target.value==='fault';go('home')};$('#reset').onclick=()=>{record=null;completed=false;fault=false;condition='변화 없음';try{localStorage.removeItem('blue-shelter-record')}catch{}$('#scenario').value='normal';go('home');toast('시연을 처음부터 시작해요')};$('.brand').onclick=e=>{e.preventDefault();go('home')};$('#fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{toast('브라우저의 전체 화면 기능을 이용해 주세요')}};render();
